{
  "outcome": "escalate",
  "rationale": "We are escalating this claim because an automated fraud flag was raised for an inflated estimate. Section [STD-7.3] governs this situation when the amount claimed is substantially higher than the usual repair cost, requiring review.",
  "citations": [
    {
      "clause_id": "STD-7.3",
      "quote": "If the amount claimed is substantially higher than the usual cost of repairing the damage described, or is not supported by the itemized estimate, the claim must be escalated for review."
    }
  ]
}
